\begin{document}

	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}
	\pagestyle{empty}

	\begin{tikzpicture}[scale=0.6, tdplot_main_coords,axis/.style={->,dashed},thick]
	\def\acolor{deepskyblue}


	\def\H{8}
	\def\h{5}
	\def\R{3}
	\def\ang{20}
	\pgfmathsetmacro{\c}{cos(\ang)}
	\pgfmathsetmacro{\s}{sin(\ang)}
	\pgfmathsetmacro{\r}{\h/\H*\R}
	\pgfmathsetmacro{\dh}{\H-\h}



	\tikzstyle{redfill} = [thick,\acolor!90,fill=\acolor!40, fill opacity=0.7]
	\tikzstyle{redfilllight} = [thick, \acolor!90,fill=\acolor!40, fill opacity=0.2]

	\coordinate  (O) at ( 0, 0, 0){};
	\coordinate  (A) at ( 0, 0, -\H){};
	\coordinate  (B) at ( {\c*\R}, {-\s*\R}, 0){};
	\coordinate  (C) at ( {-\c*\R}, {-\s*\R}, 0){};
	\coordinate  (O2) at ( 0, 0, -\dh){};
	\coordinate  (b) at ( {\c*\r}, {-\s*\r}, -\dh){};
	\coordinate  (c) at (  {-\c*\r}, {-\s*\r}, -\dh){};

	\coordinate  (R2) at ({cos(230)*\r},  {sin(230)*\r}, -\dh){};
	\coordinate  (R) at ({cos(230)*\R}, {sin(230)*\R}, 0){};
	\coordinate  (P) at ({\R}, 0, -\H){};
	\coordinate  (Q) at ({\R}, 0, 0){};

	\coordinate  (aa) at (  {\r}, 0, -\H){};
	\coordinate  (bb) at (  {\r}, 0, -\dh){};

	\begin{scope}[canvas is xy plane at z=.4]
        	\draw[redfill,dotted] (O2) circle (\r);
        	\draw[redfill] (A) -- (b) arc ({0-\ang}:{-180+\ang}:\r) -- cycle ;
	\end{scope}
	\draw[dashed, opacity=0.5] (O2) -- (A);
	\tkzDrawVector[opacity=0.5](O,R)
	\tkzLabelSegment[sloped, above, yshift=-0pt](O,R){\small $R=15\,\textrm{cm}$}
	\tkzDrawVector[dashed, opacity=0.5](O2,R2)
	\tkzLabelSegment[sloped, above](O2,R2){\small $r$}
	\draw[dashed, opacity=0.5] (O) -- (O2);
	%\tkzDrawLine[add = 0 and 0.2cm, opacity=0.5](A,P)
        \tkzDrawLine[very thin, add = 0 and 0.2cm, opacity=0.5](A,P)
        \tkzDrawLine[very thin, add = 0 and 0.2cm, opacity=0.5](O2,bb)
        \tkzDrawLine[very thin, add = 0 and 0.2cm, opacity=0.5](O,Q)
        		\draw[very thin,<            ->] (bb) -- (aa);
		\tkzLabelSegment[right](aa,bb){\small $h$}

	\draw[very thin,<                  ->, opacity=0.5] (P) -- (Q);
	\tkzLabelSegment[right](P,Q){\small $H=75\,\text{cm}$}


	\begin{scope}[canvas is xy plane at z=0]
       	\draw[redfilllight](0,0) circle (\R);
      	\draw[redfilllight] (b) -- (B) arc ({0-\ang}:{-180+\ang}:\R) -- (c) arc ({-180+\ang}:{0-\ang}:\r) --  cycle  ;
	\end{scope}

	\end{tikzpicture}

